// =============================================================================
// Kun Like 桌宠 · DSH 动态插件（Host 半）
// 用于 DSH 的 cordis_define 工具：code.host 字段
//
// 职责：
//   1. 读取本地素材（精灵图 + 完成音），通过 webServer 注册 HTTP 路由
//   2. 轮询 agents 服务，按 Agent 的 running → idle 转换推导桌宠状态
//   3. 任务完成时由宿主进程播放「你干嘛~哎哟」（系统级，全窗口可闻）
//   4. 提供 pet-state RPC 与 kun_pet_debug 调试工具
//   5. 拉起系统级 WPF 透明置顶悬浮窗（唯一的桌宠，覆盖所有窗口），
//      通过 /kun-pet/state 路由同步状态，并提供 kun_pet_window 控制工具
//
// 权限说明：沙箱令牌（workspace-write）会移除 INTERACTIVE SID，导致音频
//       端点被拒（点击/庆祝语音无声），因此悬浮窗进程与语音播放命令
//       使用 sandboxPolicy = danger-full-access（命令与脚本均为固定内容）。
//
// 素材说明：原始 spritesheet.webp 的 alpha 丢失，改用清理后的
//       kunpet-sprite.png（透明背景、绿边已除）。
// =============================================================================

// ===== 配置区（按需修改） =====
const CONFIG = {
  // 精灵图路径（清理后的 PNG：8 列 × 9 行、每格 192×208、透明背景）
  spritePath: 'D:/KUN_pet/kunpet-sprite.png',
  // 任务完成提示音路径（mp3）
  voicePath: 'D:/harness-UI/kun-like-pet/assets/voice.mp3',
  // 宿主进程系统级播放命令（Windows：WMP COM 播放 mp3，播完自动退出；macOS 可换 afplay；Linux 可换 ffplay -nodisp -autoexit）
  playCommand: (path) => "powershell -NoProfile -Command $w=New-Object -ComObject WMPlayer.OCX;$w.settings.volume=100;$w.URL='" + path.replace(/'/g, "''") + "';Start-Sleep -Milliseconds 400;$t=0.4;while($w.playState -ne 1 -and $t -lt 10){Start-Sleep -Milliseconds 250;$t+=0.25}",
  // 系统级悬浮窗脚本（WPF 透明置顶窗口）
  desktopScriptPath: 'D:/KUN_pet/kunpet-desktop.ps1',
  // 悬浮窗进程 PID 文件
  desktopPidFile: 'D:/KUN_pet/kunpet-desktop.pid',
  // 状态轮询间隔（毫秒）
  pollMs: 500,
  // 庆祝动画持续时长（毫秒）
  celebrateMs: 4800,
  // 失败动画持续时长（毫秒）
  failedMs: 2600,
}

return {
  inject: ['timer'],
  apply(ctx) {
    const fs = ctx.get('fs')
    const webServer = ctx.get('webServer')
    if (fs === undefined || webServer === undefined) {
      console.error('[kun-pet] fs or webServer service is unavailable')
      return
    }

    // 悬浮窗进程与语音播放需要完整权限（沙箱令牌会移除 INTERACTIVE SID，导致音频无声）
    const SHELL_POLICY = { mode: 'danger-full-access', workspaceRoot: 'D:/KUN_pet' }
    const shellRequest = (command) => ({ command, sandboxPolicy: SHELL_POLICY })

    // ---------- load pet assets once ----------
    let spriteBytes = null
    let voiceBytes = null
    let disposed = false
    const routeDisposers = []

    const registerRoutes = () => {
      if (spriteBytes !== null) {
        routeDisposers.push(webServer.register({
          kind: 'exact',
          path: '/kun-pet/spritesheet.png',
          handler: (req, res) => {
            res.writeHead(200, {
              'Content-Type': 'image/png',
              'Content-Length': String(spriteBytes.length),
              'Cache-Control': 'public, max-age=86400',
            })
            res.end(spriteBytes)
          },
        }))
      }
      if (voiceBytes !== null) {
        routeDisposers.push(webServer.register({
          kind: 'exact',
          path: '/kun-pet/voice.mp3',
          handler: (req, res) => {
            res.writeHead(200, {
              'Content-Type': 'audio/mpeg',
              'Content-Length': String(voiceBytes.length),
              'Cache-Control': 'public, max-age=86400',
            })
            res.end(voiceBytes)
          },
        }))
      }
    }

    const loadAssets = async () => {
      try {
        const target = await fs.resolve(CONFIG.spritePath)
        spriteBytes = await fs.readBytes(target, undefined, 16 * 1024 * 1024)
        console.log('[kun-pet] spritesheet loaded:', spriteBytes.length, 'bytes')
      } catch (err) {
        console.error('[kun-pet] failed to load spritesheet:', err)
      }
      try {
        const target = await fs.resolve(CONFIG.voicePath)
        voiceBytes = await fs.readBytes(target, undefined, 8 * 1024 * 1024)
        console.log('[kun-pet] voice loaded:', voiceBytes.length, 'bytes')
      } catch (err) {
        console.error('[kun-pet] failed to load voice:', err)
      }
      if (!disposed) registerRoutes()
    }
    const assetsReady = loadAssets()

    // ---------- pet state machine (polling-driven) ----------
    let mode = 'idle'
    let seq = 0
    let celebrating = false
    let celebrateTimer = null
    let failTimer = null
    let celebrateCount = 0
    let workMarks = 0
    let errorMarks = 0
    let transitionsSeen = 0
    let pollCount = 0
    let rawExecute = 0
    let rawApproval = 0
    let rawRequestError = 0
    let toolsInFlight = 0
    let recentTool = false
    let recentToolTimer = null
    let waitingCount = 0
    let lastAgentStatuses = []
    let lastPlayError = null

    // ---------- state route for the system-wide desktop pet window ----------
    routeDisposers.push(webServer.register({
      kind: 'exact',
      path: '/kun-pet/state',
      handler: (req, res) => {
        res.writeHead(200, {
          'Content-Type': 'application/json',
          'Cache-Control': 'no-store',
        })
        res.end(JSON.stringify({ mode, seq }))
      },
    }))

    // ---------- system-wide desktop pet window (WPF overlay) ----------
    let desktopProc = null
    let desktopLaunchError = null
    let desktopStartCount = 0
    let desktopLog = ''

    const readProcOutput = (p) => {
      try {
        if (!p || typeof p.readOutput !== 'function') return ''
        const out = p.readOutput()
        if (out === undefined || out === null) return ''
        let s = ''
        if (typeof out === 'string') s = out
        else if (typeof out === 'object') {
          if (typeof out.stderr === 'string') s += 'stderr: ' + out.stderr
          if (typeof out.stdout === 'string') s += (s ? ' | ' : '') + 'stdout: ' + out.stdout
          if (typeof out.delta === 'string') s += (s ? ' | ' : '') + out.delta
          if (s === '') {
            try { s = JSON.stringify(out) } catch (err) { s = '' }
          }
        }
        return String(s).slice(0, 1000)
      } catch (err) {
        return 'readOutput failed: ' + String(err && err.message ? err.message : err)
      }
    }

    const launchDesktopPet = () => {
      if (desktopProc !== null) return
      const shell = ctx.get('shell')
      if (shell === undefined) {
        desktopLaunchError = 'shell service unavailable'
        return
      }
      try {
        const host = webServer.host === '0.0.0.0' ? '127.0.0.1' : webServer.host
        const base = 'http://' + host + ':' + webServer.port
        const cmd = 'powershell.exe -NoProfile -ExecutionPolicy Bypass -WindowStyle Hidden -File "' + CONFIG.desktopScriptPath + '"' +
          ' -StateUrl "' + base + '/kun-pet/state"' +
          ' -SpriteUrl "' + base + '/kun-pet/spritesheet.png"' +
          ' -SpritePath "' + CONFIG.spritePath + '"' +
          ' -VoicePath "' + CONFIG.voicePath + '"' +
          ' -PidFile "' + CONFIG.desktopPidFile + '"'
        const spec = shell.resolve(shellRequest(cmd))
        desktopProc = shell.start(spec)
        desktopStartCount++
        desktopLaunchError = null
        desktopLog = ''
        console.log('[kun-pet] desktop pet window process started')
        const p = desktopProc
        if (p && typeof p.readOutput === 'function') {
          ctx.timeout(() => {
            if (desktopProc !== p) return
            const s = readProcOutput(p)
            if (s) desktopLog = s
          }, 3000)
        }
        if (p && p.done && typeof p.done.then === 'function') {
          p.done.then(
            () => {
              if (desktopProc === p) desktopProc = null
              const s = readProcOutput(p)
              if (s) {
                desktopLog = s
                desktopLaunchError = 'desktop process exited: ' + s.slice(0, 300)
              } else {
                desktopLaunchError = 'desktop process exited without output'
              }
              console.error('[kun-pet] desktop pet window exited:', desktopLaunchError)
            },
            () => { if (desktopProc === p) desktopProc = null },
          )
        }
      } catch (err) {
        desktopProc = null
        desktopLaunchError = String(err && err.message ? err.message : err)
        console.error('[kun-pet] failed to start desktop pet window:', err)
      }
    }

    const stopDesktopPet = () => {
      if (desktopProc !== null) {
        try {
          if (typeof desktopProc.kill === 'function') desktopProc.kill()
        } catch (err) { /* ignore */ }
        desktopProc = null
      }
      return (async () => {
        try {
          const target = await fs.resolve(CONFIG.desktopPidFile)
          const text = await fs.readText(target)
          const pid = parseInt(String(text).trim(), 10)
          if (Number.isFinite(pid) && pid > 0) {
            const shell = ctx.get('shell')
            if (shell !== undefined) {
              const spec = shell.resolve(shellRequest('taskkill /F /PID ' + pid))
              await shell.run(spec)
            }
          }
        } catch (err) { /* ignore */ }
      })()
    }

    assetsReady.then(() => { if (!disposed) launchDesktopPet() })

    const turnFlags = new WeakMap() // agent -> { worked, errored }
    const lastStatus = new WeakMap() // agent -> 'idle' | 'running'
    const observedAgents = new Set()
    let flagEntries = 0
    const flagsOf = (agent) => {
      let f = turnFlags.get(agent)
      if (f === undefined) {
        f = { worked: false, errored: false }
        turnFlags.set(agent, f)
        flagEntries++
      }
      return f
    }

    const lastStatusEntries = () => {
      const out = []
      for (const agent of observedAgents) {
        const s = lastStatus.get(agent)
        if (s !== undefined) out.push([agent, s])
      }
      return out
    }

    const currentRunningCount = () => {
      let n = 0
      for (const entry of lastStatusEntries()) {
        if (entry[1] === 'running') n++
      }
      return n
    }

    const setMode = (next) => {
      if (next === mode) return
      if (celebrating && next !== 'celebrating') return
      mode = next
      seq++
    }

    const deriveMode = (runningCount) => {
      if (celebrating) return
      let next
      if (waitingCount > 0) next = 'waiting'
      else if (runningCount > 0) next = (toolsInFlight > 0 || recentTool) ? 'working' : 'review'
      else next = 'idle'
      setMode(next)
    }

    const playSystemVoice = () => {
      const shell = ctx.get('shell')
      if (shell === undefined) {
        lastPlayError = 'shell service unavailable'
        return
      }
      try {
        const spec = shell.resolve(shellRequest(CONFIG.playCommand(CONFIG.voicePath)))
        shell.run(spec).catch((err) => {
          lastPlayError = String(err && err.message ? err.message : err)
        })
        lastPlayError = null
      } catch (err) {
        lastPlayError = String(err && err.message ? err.message : err)
        console.error('[kun-pet] failed to start voice playback:', err)
      }
    }

    const celebrate = () => {
      if (celebrating) {
        // Extend the ongoing celebration; never double-fire the sound.
        if (celebrateTimer) celebrateTimer()
        celebrateTimer = ctx.timeout(() => {
          celebrateTimer = null
          celebrating = false
          deriveMode(currentRunningCount())
        }, CONFIG.celebrateMs)
        return
      }
      celebrateCount++
      celebrating = true
      setMode('celebrating')
      playSystemVoice()
      celebrateTimer = ctx.timeout(() => {
        celebrateTimer = null
        celebrating = false
        deriveMode(currentRunningCount())
      }, CONFIG.celebrateMs)
    }

    const showFailed = () => {
      if (celebrating) return
      setMode('failed')
      if (failTimer) failTimer()
      failTimer = ctx.timeout(() => {
        failTimer = null
        deriveMode(currentRunningCount())
      }, CONFIG.failedMs)
    }

    const markToolSettled = (wasQuestion) => {
      toolsInFlight = Math.max(0, toolsInFlight - 1)
      if (wasQuestion) {
        waitingCount = Math.max(0, waitingCount - 1)
      }
      if (toolsInFlight === 0) {
        if (recentToolTimer) recentToolTimer()
        recentToolTimer = ctx.timeout(() => {
          recentToolTimer = null
          recentTool = false
          deriveMode(currentRunningCount())
        }, 2500)
      }
      deriveMode(currentRunningCount())
    }

    ctx.effect(() => () => {
      disposed = true
      for (const d of routeDisposers) d()
      if (celebrateTimer) celebrateTimer()
      if (failTimer) failTimer()
      if (recentToolTimer) recentToolTimer()
      stopDesktopPet()
    })

    // ---------- polling: live agent statuses ----------
    const agentsService = ctx.get('agents')
    const poll = () => {
      pollCount++
      if (agentsService === undefined) return
      let list
      try {
        list = agentsService.list()
      } catch (err) {
        return
      }
      if (!Array.isArray(list)) return
      const runningNow = new Set()
      const statuses = []
      for (const agent of list) {
        let status = 'idle'
        try {
          status = agent && agent.status === 'running' ? 'running' : 'idle'
        } catch (err) {
          status = 'idle'
        }
        statuses.push(status)
        if (status === 'running') runningNow.add(agent)
        const prev = lastStatus.get(agent)
        lastStatus.set(agent, status)
        if (agent && prev === undefined) observedAgents.add(agent)
        if (prev === 'running' && status === 'idle') {
          transitionsSeen++
          if (runningNow.size === 0 && waitingCount === 0) {
            const f = turnFlags.get(agent)
            if (f === undefined || !f.errored) celebrate()
            if (f !== undefined) {
              turnFlags.delete(agent)
              flagEntries--
            }
          }
        }
      }
      lastAgentStatuses = statuses
      deriveMode(runningNow.size)
    }
    const stopPolling = ctx.interval(poll, CONFIG.pollMs)
    ctx.effect(() => stopPolling)

    // ---------- waterfalls (waiting + errors) ----------
    ctx.on('approval/request', (req, next) => {
      rawApproval++
      waitingCount++
      deriveMode(currentRunningCount())
      let p
      try {
        p = Promise.resolve(next())
      } catch (err) {
        waitingCount = Math.max(0, waitingCount - 1)
        deriveMode(currentRunningCount())
        throw err
      }
      p.then(
        () => { waitingCount = Math.max(0, waitingCount - 1); deriveMode(currentRunningCount()) },
        () => { waitingCount = Math.max(0, waitingCount - 1); deriveMode(currentRunningCount()) },
      )
      return p
    })

    ctx.on('tools/execute', (exec, next) => {
      rawExecute++
      let isQuestion = false
      if (exec && exec.agent) {
        flagsOf(exec.agent).worked = true
        workMarks++
      }
      if (exec && typeof exec.name === 'string' && exec.name === 'ask_user_question') {
        isQuestion = true
        waitingCount++
      }
      toolsInFlight++
      recentTool = true
      if (recentToolTimer) {
        recentToolTimer()
        recentToolTimer = null
      }
      deriveMode(currentRunningCount())
      let p
      try {
        p = Promise.resolve(next())
      } catch (err) {
        markToolSettled(isQuestion)
        throw err
      }
      p.then(
        () => markToolSettled(isQuestion),
        () => markToolSettled(isQuestion),
      )
      return p
    })

    ctx.on('agent/request-error', (payload, next) => {
      rawRequestError++
      if (payload && payload.agent) {
        flagsOf(payload.agent).errored = true
        errorMarks++
      }
      showFailed()
      return next()
    })

    // ---------- client RPC ----------
    harness.handle('pet-state', async () => {
      await assetsReady
      const host = webServer.host === '0.0.0.0' ? '127.0.0.1' : webServer.host
      const base = 'http://' + host + ':' + webServer.port
      return {
        mode,
        seq,
        spriteUrl: spriteBytes !== null ? base + '/kun-pet/spritesheet.png' : null,
        voiceUrl: voiceBytes !== null ? base + '/kun-pet/voice.mp3' : null,
      }
    })

    // ---------- debug tool ----------
    harness.registerTool(ctx, harness.defineTool({
      name: 'kun_pet_debug',
      description: 'Read the Kun Like desktop-pet state machine internals and polling counters. Use only to diagnose pet behavior.',
      parameters: {},
      output: {
        schema: { type: 'json' },
        render: (_args, value) => [{ type: 'text', text: JSON.stringify(value, null, 2) }],
      },
      execute() {
        return Promise.resolve({
          mode,
          seq,
          celebrating,
          celebrateCount,
          workMarks,
          errorMarks,
          transitionsSeen,
          flagEntries,
          waitingCount,
          toolsInFlight,
          recentTool,
          pollCount,
          agentCount: lastAgentStatuses.length,
          lastAgentStatuses,
          lastPlayError,
          desktop: {
            running: desktopProc !== null,
            startCount: desktopStartCount,
            launchError: desktopLaunchError,
            log: desktopLog,
          },
          raw: {
            execute: rawExecute,
            approval: rawApproval,
            requestError: rawRequestError,
          },
        })
      },
    }))

    // ---------- desktop window control tool ----------
    harness.registerTool(ctx, harness.defineTool({
      name: 'kun_pet_window',
      description: 'Control the Kun Like system-wide desktop pet overlay window (Windows WPF, floats above all applications). Use start to (re)launch it, stop to close it, status to check whether it is running.',
      parameters: {
        type: 'object',
        properties: {
          action: { type: 'string', enum: ['start', 'stop', 'status'] },
        },
        required: ['action'],
      },
      output: {
        schema: { type: 'json' },
        render: (_args, value) => [{ type: 'text', text: JSON.stringify(value, null, 2) }],
      },
      execute(args) {
        if (args.action === 'start') {
          if (desktopProc !== null) return Promise.resolve({ ok: true, status: 'already-running' })
          launchDesktopPet()
          return Promise.resolve({
            ok: desktopProc !== null,
            status: desktopProc !== null ? 'launched' : 'failed',
            error: desktopLaunchError,
          })
        }
        if (args.action === 'stop') {
          return stopDesktopPet().then(() => ({ ok: true, status: 'stopped' }))
        }
        return Promise.resolve({
          ok: true,
          running: desktopProc !== null,
          startCount: desktopStartCount,
          error: desktopLaunchError,
        })
      },
    }))
  },
}
